-- Care Guides reference content
-- Run this once in the Supabase SQL Editor, after schema.sql.

create table public.care_guides (
  id uuid primary key default gen_random_uuid(),
  species_type text not null check (species_type in ('dog', 'cat', 'small_animal', 'reptile', 'fish')),
  name text not null,
  lifespan text,
  temp text,
  humidity text,
  enclosure_size text,
  diet text,
  note text,
  created_at timestamptz not null default now()
);

-- Reference content, same for every user: readable by any signed-in user,
-- writable only from the Supabase dashboard (no insert/update/delete policy).
alter table public.care_guides enable row level security;

create policy "care_guides: readable by any signed-in user" on public.care_guides
  for select using (auth.role() = 'authenticated');

